const strangeSortList = (lst) => {
  if (lst.length === 0) return [];
  const sorted = [...lst].sort((a, b) => a - b);
  const result = [];
  let left = 0;
  let right = sorted.length - 1;
  let toggle = true;
  while (left <= right) {
    if (toggle) {
      result.push(sorted[left]);
      left++;
    } else {
      result.push(sorted[right]);
      right--;
    }
    toggle = !toggle;
  }
  return result;
};

